// ig-proto, variant ps-levels (stages 2 to 4 pack T06b, plan 4.1): the per-set prior only on the levels listed in
// IG.perSetLevels (the freeze: ['hell-1']); without the parameter (undefined or null), on every level as in v4-ps.
import { IG as IG_PSL } from '../engine/ig-params.js';

/**
 * @param {string} levelId
 * @param {any} [levels] IG.perSetLevels by default.
 * @returns {boolean}
 */
export function igPerSetLevel(levelId, levels = IG_PSL.perSetLevels) {
  return levels === undefined || levels === null || (Array.isArray(levels) && levels.includes(levelId));
}
